        @Override
        public void setMixins(NodeId nodeId, Name[] mixinNodeTypeIds) throws RepositoryException {
            checkConsumed();
            try {
                DavPropertySet setProperties;
                DavPropertyNameSet removeProperties;
                if (mixinNodeTypeIds == null || mixinNodeTypeIds.length == 0) {
