            CloudFoundryClient cloudFoundryClient,
            PushApplicationRequest request,
            String spaceId,
            String stackId,
            String applicationId) {
        CreateApplicationRequest.Builder requestBuilder = CreateApplicationRequest.builder();
        requestBuilder.dockerCredentials(
                DockerCredentials.builder()
                        .username(request.getDockerUsername())
                        .password(request.getDockerPassword())
                        .build());

        when(cloudFoundryClient
                        .applicationsV2()
                        .create(
                                requestBuilder
                                        .command(request.getCommand())
                                        .diego(true)
                                        .diskQuota(request.getDiskQuota())
                                        .dockerImage(request.getDockerImage())
                                        .healthCheckTimeout(request.getTimeout())
                                        .healthCheckType(
                                                Optional.ofNullable(request.getHealthCheckType())
                                                        .map(ApplicationHealthCheck::getValue)
                                                        .orElse(null))
                                        .instances(request.getInstances())
                                        .memory(request.getMemory())
                                        .name(request.getName())
                                        .spaceId(spaceId)
                                        .stackId(stackId)
                                        .build()))
                .thenReturn(
                        Mono.just(
                                fill(CreateApplicationResponse.builder(), "create-")
