    		List<String> values = this.innerMap.get(key);
    		if (values == null) {
    			values = new ArrayList<String>();
    			this.innerMap.put(key, values);
    		}

    		for (String newvalue : newvalues) {
				values.add(newvalue);
            }
        }

		public boolean isEmpty() {
	        return this.innerMap.isEmpty();
        }

