    private static final Logger log = LoggerFactory.getLogger(PTSAFTFileGenerator.class);

    private Config config = null;
    private JAXBContext jaxbContext;
    private Marshaller marshaller;
    private MathContext mc = BillyMathContext.get();

    private String context = null;
    private String optionalParam;

    private static final String FILE_ENCODING = "UTF-8";

    private final int MAX_LENGTH_1 = 1;
    private final int MAX_LENGTH_2 = 2;
    private final int MAX_LENGTH_3 = 3;
    private final int MAX_LENGTH_5 = 5;
    private final int MAX_LENGTH_8 = 8;
    private final int MAX_LENGTH_9 = 9;
    private final int MAX_LENGTH_10 = 10;
    private final int MAX_LENGTH_12 = 12;
    private final int MAX_LENGTH_20 = 20;
    private final int MAX_LENGTH_30 = 30;
    private final int MAX_LENGTH_40 = 40;
    private final int MAX_LENGTH_50 = 50;
    private final int MAX_LENGTH_60 = 60;
    private final int MAX_LENGTH_90 = 90;
    private final int MAX_LENGTH_100 = 100;
    private final int MAX_LENGTH_172 = 172;
    private final int MAX_LENGTH_200 = 200;
    private final int MAX_LENGTH_255 = 255;

    private final String XML_SCHEMA_VERSION = "1.02_01";
    private final String TAX_ACCOUNTING_BASIS = "F";
    private final String COUNTRY_CODE = "PT";
    private final String CURRENCY_CODE = "EUR";
    private final String TAX_ENTITY = "Global";

    private final String ACCOUNT_ID = "Desconhecido";
    private final String SELF_BILLING_INDICATOR = "0";
    private final String UNIT_OF_MEASURE = "Unidade";

    private final DAOPTCustomer daoCustomer;
    private final DAOPTSupplier daoSupplier;
    private final DAOPTProduct daoProduct;
    private final DAOPTTax daoPTTax;
    private final DAOPTRegionContext daoPTRegionContext;
    private final DAOPTInvoice daoPTInvoice;
    private final DAOPTSimpleInvoice daoPTSimpleInvoice;
    private final DAOPTReceiptInvoice daoPTReceiptInvoice;
    private final DAOPTCreditNote daoPTCreditNote;

    @Inject
    public PTSAFTFileGenerator(DAOPTCustomer daoCustomer, DAOPTSupplier daoSupplier, DAOPTProduct daoProduct,
            DAOPTTax daoPTTax, DAOPTRegionContext daoPTRegionContext, DAOPTInvoice daoPTInvoice,
            DAOPTSimpleInvoice daoPTSimpleInvoice, DAOPTReceiptInvoice daoPTReceiptInvoice,
            DAOPTCreditNote daoPTCreditNote) {
        this.daoCustomer = daoCustomer;
        this.daoSupplier = daoSupplier;
        this.daoProduct = daoProduct;
        this.daoPTTax = daoPTTax;
        this.daoPTRegionContext = daoPTRegionContext;
        this.daoPTInvoice = daoPTInvoice;
        this.daoPTSimpleInvoice = daoPTSimpleInvoice;
        this.daoPTReceiptInvoice = daoPTReceiptInvoice;
        this.daoPTCreditNote = daoPTCreditNote;

        this.config = new Config();

        try {
            this.jaxbContext =
                    JAXBContext.newInstance("com.premiumminds.billy.portugal.services.export.saftpt.v1_02_01.schema");
            this.marshaller = this.jaxbContext.createMarshaller();
        } catch (Exception e) {
            log.error("Problems with JAXBContext", e);
        }
    }

    /**
     * Constructs a new SAFT a.k.a. AuditFile
     *
     * @param targetStream
     *
     * @param businessEntity
     *        - the company
     * @param application
     * @param certificateNumber
     * @param fromDate
     * @param toDate
     * @param daoCustomer
     * @param daoSupplier
     * @param daoProduct
     * @param daoPTTax
     * @param daoPTRegionContext
     * @param daoPTInvoice
     * @param daoPTSimpleInvoice
     * @param daoPTCreditNote
     * @return the SAFT for that business entity, given lists of customers,
     *         products, taxes and financial documents; depends on a period of
     *         time
     * @throws SAFTPTExportException
     */
    public void generateSAFTFile(final OutputStream targetStream, final PTBusinessEntity businessEntity,
            final PTApplicationEntity application, final String certificateNumber, final Date fromDate,
            final Date toDate) throws SAFTPTExportException {

        try {
            new TransactionWrapper<AuditFile>(this.daoPTInvoice) {

                @Override
                public AuditFile runTransaction() throws Exception {
                    AuditFile SAFTFile = new AuditFile();

                    /* HEADER */
                    Header hdr = PTSAFTFileGenerator.this.generateHeader(businessEntity, application, certificateNumber,
                            fromDate, toDate);
                    SAFTFile.setHeader(hdr);

                    /* MASTER FILES */
                    MasterFiles mf = new MasterFiles();

                    // Customers
                    @SuppressWarnings("unchecked")
                    List<PTCustomerEntity> customers =
                            (List<PTCustomerEntity>) (List<?>) PTSAFTFileGenerator.this.daoCustomer
                                    .getAllActiveCustomers();
                    for (PTCustomerEntity customer : customers) {
                        Customer SAFTCustomer = PTSAFTFileGenerator.this.generateCustomer(customer);
                        mf.getCustomer().add(SAFTCustomer);
                    }

                    // Suppliers
                    @SuppressWarnings("unchecked")
                    List<PTSupplierEntity> suppliers =
                            (List<PTSupplierEntity>) (List<?>) PTSAFTFileGenerator.this.daoSupplier
                                    .getAllActiveSuppliers();
                    for (PTSupplierEntity sup : suppliers) {
                        Supplier SAFTSupplier = PTSAFTFileGenerator.this.generateSupplier(sup);
                        mf.getSupplier().add(SAFTSupplier);
                    }

                    // Products
                    @SuppressWarnings("unchecked")
                    List<PTProductEntity> products =
                            (List<PTProductEntity>) (List<?>) PTSAFTFileGenerator.this.daoProduct
                                    .getAllActiveProducts();
                    for (PTProductEntity prod : products) {
                        Product SAFTProduct = PTSAFTFileGenerator.this.generateProduct(prod);
                        mf.getProduct().add(SAFTProduct);
                    }

                    PTRegionContextEntity context = (PTRegionContextEntity) PTSAFTFileGenerator.this.daoPTRegionContext
                            .get(PTSAFTFileGenerator.this.config.getUID(Config.Key.Context.Portugal.UUID));
                    // Taxes
                    @SuppressWarnings("unchecked")
                    List<PTTaxEntity> taxes = (List<PTTaxEntity>) (List<?>) PTSAFTFileGenerator.this.daoPTTax
                            .getTaxesForSAFTPT(context, null, null);
                    TaxTable SAFTTaxTable = PTSAFTFileGenerator.this.generateTaxTable(taxes);
                    mf.setTaxTable(SAFTTaxTable);
                    SAFTFile.setMasterFiles(mf);

                    /* SOURCE DOCUMENTS */
                    List<PTInvoiceEntity> invoices = PTSAFTFileGenerator.this.daoPTInvoice
                            .getBusinessInvoicesForSAFTPT(businessEntity.getUID(), fromDate, toDate);

                    List<PTSimpleInvoiceEntity> simpleInvoices = PTSAFTFileGenerator.this.daoPTSimpleInvoice
                            .getBusinessSimpleInvoicesForSAFTPT(businessEntity.getUID(), fromDate, toDate);

                    List<PTReceiptInvoiceEntity> receiptInvoices = PTSAFTFileGenerator.this.daoPTReceiptInvoice
                            .getBusinessReceiptInvoicesForSAFTPT(businessEntity.getUID(), fromDate, toDate);

                    List<PTCreditNoteEntity> creditNotes = PTSAFTFileGenerator.this.daoPTCreditNote
                            .getBusinessCreditNotesForSAFTPT(businessEntity.getUID(), fromDate, toDate);

                    SourceDocuments sd = PTSAFTFileGenerator.this.generateSourceDocuments(
                            invoices == null ? new ArrayList<PTInvoiceEntity>() : invoices,
                            simpleInvoices == null ? new ArrayList<PTSimpleInvoiceEntity>() : simpleInvoices,
                            receiptInvoices == null ? new ArrayList<PTReceiptInvoiceEntity>() : receiptInvoices,
                            creditNotes == null ? new ArrayList<PTCreditNoteEntity>() : creditNotes);
                    SAFTFile.setSourceDocuments(sd);

                    PTSAFTFileGenerator.this.exportSAFTFile(SAFTFile, targetStream);

                    return SAFTFile;
                }
            }.execute();

        } catch (Exception e) {
            throw new SAFTPTExportException(e);
        }
    }

    /**
     * Generates the SAFT XML File
     *
     * @param auditFile
     *        that will be exported
     * @param targetStream
     */
    private void exportSAFTFile(AuditFile auditFile, OutputStream targetStream) {
        try {
            this.marshaller.setProperty(Marshaller.JAXB_ENCODING, FILE_ENCODING);
            this.marshaller.setProperty(Marshaller.JAXB_FORMATTED_OUTPUT, Boolean.TRUE);
            this.marshaller.marshal(auditFile, targetStream);

        } catch (Exception e) {
            PTSAFTFileGenerator.log.error(e.getMessage(), e);
        }
    }

    /**
     * Generates the Header of SAFT file (Table 1)
     *
     * @param businessEntity
     *        - the company
     * @param startDate
     *        , endDate - the period for the SAFT file
     * @return the Header
     * @throws DatatypeConfigurationException
     *         - problems with dates
     * @throws RequiredFieldNotFoundException
     *         - if a required field in the SAFT file could not be assigned
     * @throws InvalidContactTypeException
     */
    private Header generateHeader(PTBusinessEntity businessEntity, PTApplicationEntity application,
            String certificateNumber, Date startDate, Date endDate)
            throws DatatypeConfigurationException, RequiredFieldNotFoundException, InvalidContactTypeException {
        this.context = "Header.";

        Header hdr = new Header();
        hdr.setAuditFileVersion(
                this.validateString("AuditFileVersion", this.XML_SCHEMA_VERSION, this.MAX_LENGTH_10, true));
        hdr.setCompanyID(this.validateString("CompanyID", businessEntity.getFinancialID(), this.MAX_LENGTH_50, true));
        hdr.setTaxRegistrationNumber(this.validateInteger("TaxRegistrationNumber", businessEntity.getFinancialID(),
                this.MAX_LENGTH_9, true));
        hdr.setTaxAccountingBasis(
                this.validateString("TaxAccountBasis", this.TAX_ACCOUNTING_BASIS, this.MAX_LENGTH_1, true));
        hdr.setCompanyName(this.validateString("CompanyName", businessEntity.getName(), this.MAX_LENGTH_100, true));

        if ((this.optionalParam =
                this.validateString("BusinessName", businessEntity.getCommercialName(), this.MAX_LENGTH_60, false))
                        .length() > 0) {
            hdr.setBusinessName(this.optionalParam);
        }

        hdr.setCompanyAddress(this.generateAddressStructurePT((AddressEntity) businessEntity.getAddress()));

        hdr.setFiscalYear(this.getDateField(startDate, Calendar.YEAR));
        hdr.setStartDate(this.formatDate(startDate));
        hdr.setEndDate(this.formatDate(endDate));
        hdr.setCurrencyCode(this.validateString("CurrencyCode", this.CURRENCY_CODE, this.MAX_LENGTH_3, true));
        hdr.setDateCreated(this.getXMLGregorianCalendarNow());

        hdr.setTaxEntity(this.validateString("TaxEntity", this.TAX_ENTITY, this.MAX_LENGTH_20, true));
        hdr.setProductCompanyTaxID(this.validateString("ProductCompanyTaxID",
                application.getDeveloperCompanyTaxIdentifier(), this.MAX_LENGTH_20, true));
        hdr.setSoftwareCertificateNumber(
                this.validateBigInteger("SoftwareCertificateNumber", certificateNumber, this.MAX_LENGTH_255, true));
        hdr.setProductID(this.validateString("ProductID",
                application.getName() + "/" + application.getDeveloperCompanyName(), this.MAX_LENGTH_255, true));
        hdr.setProductVersion(
                this.validateString("ProductVersion", application.getVersion(), this.MAX_LENGTH_30, true));

        List<PTContactEntity> list = businessEntity.getContacts();
        this.setContacts(hdr, list);

        return hdr;
    }

    /**
     * Generates an instance of Customer to be inserted in the table 2.2
     * (Customer)
     *
     * @param customerEntity
     *        - the customer
     * @return an instance of Customer
     * @throws RequiredFieldNotFoundException
     * @throws InvalidContactTypeException
     */
    private Customer generateCustomer(PTCustomerEntity customerEntity)
            throws RequiredFieldNotFoundException, InvalidContactTypeException {
        this.context = "Customer.";
        Customer customer = new Customer();
        final String customerId;

        if (this.config.getUID(Key.Customer.Generic.UUID).equals(customerEntity.getUID())) {
            customerEntity.setTaxRegistrationNumber("999999990");
            customerId = "Consumidor final";
        } else {
            if ((this.optionalParam =
                    this.validateString("Contact", customerEntity.getReferralName(), this.MAX_LENGTH_50, false))
                            .length() > 0) {
                customer.setContact(this.optionalParam);
            }

            if (customerEntity.getShippingAddress() != null) {
                customer.getShipToAddress()
                        .add(this.generateAddressStructure((PTAddressEntity) customerEntity.getShippingAddress()));
            }
            List<PTContactEntity> contacts = customerEntity.getContacts();
            this.setContacts(customer, contacts);
            customerId = customerEntity.getID().toString();
        }
        this.updateCustomerGeneralInfo(customer, customerId, customerEntity.getTaxRegistrationNumber(),
                customerEntity.getName(), (PTAddressEntity) customerEntity.getBillingAddress());

        customer.setAccountID(this.validateString("AccountID", this.ACCOUNT_ID, this.MAX_LENGTH_30, true));
        customer.setSelfBillingIndicator(
                this.validateInteger("SelfBillingIndicator", this.SELF_BILLING_INDICATOR, this.MAX_LENGTH_1, true));

        return customer;
    }

    /**
     * Generates an instance of Supplier to be inserted in the table 2.3
     * (Supplier)
     *
     * @param supplierEntity
     *        - the supplier
     * @return an instance of Supplier
     * @throws RequiredFieldNotFoundException
     * @throws InvalidContactTypeException
     */
    private Supplier generateSupplier(PTSupplierEntity supplierEntity)
            throws RequiredFieldNotFoundException, InvalidContactTypeException {
        this.context = "Supplier.";
        Supplier supplier = new Supplier();

        supplier.setSupplierID(
                this.validateString("SupplierID", supplierEntity.getID().toString(), this.MAX_LENGTH_30, true));
        // No accounting support
        supplier.setAccountID(this.validateString("AccountID", this.ACCOUNT_ID, this.MAX_LENGTH_30, true));

        supplier.setSupplierTaxID(this.validateString("SupplierTaxID", supplierEntity.getTaxRegistrationNumber(),
                this.MAX_LENGTH_20, true));

        supplier.setCompanyName(
                this.validateString("CompanyName", supplierEntity.getName(), this.MAX_LENGTH_100, true));

        if ((this.optionalParam =
                this.validateString("Contact", supplierEntity.getReferralName(), this.MAX_LENGTH_50, false))
                        .length() > 0) {
            supplier.setContact(this.optionalParam);
        }

        supplier.setBillingAddress(
                this.generateSupplierAddressStructure((PTAddressEntity) supplierEntity.getBillingAddress()));

        if (supplierEntity.getShippingAddress() != null) {
            supplier.getShipFromAddress()
                    .add(this.generateSupplierAddressStructure((PTAddressEntity) supplierEntity.getShippingAddress()));
        }

        supplier.setSelfBillingIndicator(
                this.validateInteger("SelfBillingIndicator", this.SELF_BILLING_INDICATOR, this.MAX_LENGTH_1, true));

        List<PTContactEntity> contacts = supplierEntity.getContacts();

        this.setContacts(supplier, contacts);

        return supplier;
    }

    /**
     * Generates an instance of Product to be inserted in the table 2.4
     * (Product)
     *
     * @param productEntity
     *        - the product/service
     * @return an instance of Product
     * @throws RequiredFieldNotFoundException
     * @throws InvalidProductTypeException
     */
    private Product generateProduct(PTProductEntity productEntity)
            throws RequiredFieldNotFoundException, InvalidProductTypeException {
        this.context = "Product.";

        Product product = new Product();
        product.setProductType(this.validateString("ProductType", this.getProductType(productEntity.getType()),
                this.MAX_LENGTH_1, true));

        product.setProductCode(
                this.validateString("ProductCode", productEntity.getID().toString(), this.MAX_LENGTH_30, true));

        product.setProductGroup(
                this.validateString("ProductGroup", productEntity.getProductGroup(), this.MAX_LENGTH_50, false));

        product.setProductDescription(
                this.validateString("ProductDescription", productEntity.getDescription(), this.MAX_LENGTH_200, true));

        if (productEntity.getNumberCode() == null || productEntity.getNumberCode().length() == 0) {
            product.setProductNumberCode(
                    this.validateString("ProductCode", productEntity.getID().toString(), this.MAX_LENGTH_50, true));
        } else {
            product.setProductNumberCode(
                    this.validateString("ProductCode", productEntity.getNumberCode(), this.MAX_LENGTH_50, true));
        }

        return product;
    }

    /**
     * Generates the TaxTable of SAFT file (Table 2.5)
     *
     * @param taxEntities
     *        - the taxes to be inserted in this table
     * @return
     * @throws DatatypeConfigurationException
     * @throws RequiredFieldNotFoundException
     * @throws InvalidTaxTypeException
     * @throws InvalidTaxCodeException
     */
    private TaxTable generateTaxTable(List<PTTaxEntity> taxEntities) throws DatatypeConfigurationException,
            RequiredFieldNotFoundException, InvalidTaxTypeException, InvalidTaxCodeException {
        this.context = "TaxTable.";

        TaxTable taxTable = new TaxTable();
        for (PTTaxEntity taxEntity : taxEntities) {
            TaxTableEntry tte = new TaxTableEntry();
            tte.setTaxType(this.validateString("TaxType", this.getTaxType(taxEntity), this.MAX_LENGTH_3, true));
            tte.setTaxCode(this.validateString("TaxCode", taxEntity.getCode(), this.MAX_LENGTH_10, true));
            tte.setTaxCountryRegion(this.validateString("TaxCountryRegion",
                    this.getRegionCodeFromISOCode(((PTRegionContext) taxEntity.getContext()).getRegionCode()),
                    this.MAX_LENGTH_5, true));

            tte.setDescription(
                    this.validateString("Description", taxEntity.getDescription(), this.MAX_LENGTH_255, true));

            if (taxEntity.getValidTo() != null) {
                tte.setTaxExpirationDate(this.formatDate(taxEntity.getValidTo()));
            }

            if (taxEntity.getTaxRateType().equals(TaxRateType.FLAT)) {
                tte.setTaxAmount(taxEntity.getValue());
            } else if (taxEntity.getTaxRateType().equals(TaxRateType.PERCENTAGE)) {
                tte.setTaxPercentage(taxEntity.getValue());
            } else if (taxEntity.getTaxRateType().equals(TaxRateType.NONE)) {
                tte.setTaxPercentage(BigDecimal.ZERO);
            }

            taxTable.getTaxTableEntry().add(tte);
        }

        return taxTable;
    }

    /**
     * Generates the SourceDocuments of SAFT file (Table 4)
     *
     * @param invoices
     *        - list of invoices
     * @param simpleInvoices
     *        - list of simple invoices
     * @param creditNotes
     *        - list of credit notes
     * @return
     * @throws DatatypeConfigurationException
     * @throws RequiredFieldNotFoundException
     * @throws InvalidDocumentTypeException
     * @throws InvalidDocumentStateException
     * @throws InvalidTaxTypeException
     * @throws InvalidTaxCodeException
     * @throws InvalidPaymentMechanismException
     * @throws InvalidInvoiceTypeException
     */
    private SourceDocuments generateSourceDocuments(List<PTInvoiceEntity> invoices,
            List<PTSimpleInvoiceEntity> simpleInvoices, List<PTReceiptInvoiceEntity> receiptInvoices,
            List<PTCreditNoteEntity> creditNotes) throws DatatypeConfigurationException, RequiredFieldNotFoundException,
            InvalidDocumentTypeException, InvalidDocumentStateException, InvalidTaxTypeException,
            InvalidTaxCodeException, InvalidPaymentMechanismException, InvalidInvoiceTypeException {
        this.context = "SourceDocuments.";

        SourceDocuments srcDocs = new SourceDocuments();
        SalesInvoices salesInvoices = new SalesInvoices();
        salesInvoices.setNumberOfEntries(new BigInteger(Integer
                .toString(invoices.size() + simpleInvoices.size() + receiptInvoices.size() + creditNotes.size())));

        BigDecimal totalDebit = BigDecimal.ZERO;
        BigDecimal totalCredit = BigDecimal.ZERO;

        totalCredit = this.processInvoices(invoices, salesInvoices, totalCredit);
        totalCredit = this.processInvoices(simpleInvoices, salesInvoices, totalCredit);
        totalCredit = this.processInvoices(receiptInvoices, salesInvoices, totalCredit);

        totalDebit = this.processInvoices(creditNotes, salesInvoices, totalDebit);

        salesInvoices.setTotalDebit(this.validateBigDecimal(totalDebit));
        salesInvoices.setTotalCredit(this.validateBigDecimal(totalCredit));
        srcDocs.setSalesInvoices(salesInvoices);

        return srcDocs;
    }

    private <T extends PTGenericInvoiceEntity> BigDecimal processInvoices(List<T> invoices, SalesInvoices salesInvoices,
            BigDecimal totalCredit) throws DatatypeConfigurationException, RequiredFieldNotFoundException,
            InvalidDocumentTypeException, InvalidDocumentStateException, InvalidInvoiceTypeException,
            InvalidTaxTypeException, InvalidTaxCodeException, InvalidPaymentMechanismException {
        Invoice saftInvoice;
        for (T invoice : invoices) {
            saftInvoice = this.generateSAFTInvoice(invoice);
            this.processDocument(saftInvoice, invoice, true);
            salesInvoices.getInvoice().add(saftInvoice);

            if (!invoice.isBilled() && !invoice.isCancelled()) {
                totalCredit = totalCredit.add(invoice.getAmountWithoutTax());
            }
        }
        return totalCredit;
    }

    /**
     * Generates a financial document that will be inserted in the
     * SourceDocuments table
     *
     * @param document
     *        - can be an invoice, simple invoice or credit note
     * @param documentType
     * @return an instance of Invoice (represents a financial document in the
     *         SAFT XML context)
     *
     * @throws DatatypeConfigurationException
     * @throws RequiredFieldNotFoundException
     * @throws InvalidDocumentTypeException
     * @throws InvalidDocumentStateException
     * @throws InvalidInvoiceTypeException
     */
    private Invoice generateSAFTInvoice(PTGenericInvoiceEntity document)
            throws DatatypeConfigurationException, RequiredFieldNotFoundException, InvalidDocumentTypeException,
            InvalidDocumentStateException, InvalidInvoiceTypeException {
        Invoice saftInv = new Invoice();

        saftInv.setDocumentStatus(this.getDocumentStatus(document));

        saftInv.setInvoiceNo(this.validateString("InvoiceNo", document.getNumber(), this.MAX_LENGTH_60, true));
        saftInv.setInvoiceType(
                this.validateString("InvoiceType", this.getDocumentType(document), this.MAX_LENGTH_2, true));
        saftInv.setHash(this.validateString("Hash", document.getHash(), this.MAX_LENGTH_172, true));
        if (document.getHashControl() != null) {
            saftInv.setHashControl(
                    this.validateString("HashControl", document.getHashControl(), this.MAX_LENGTH_40, false));
        }
        saftInv.setPeriod(this.validateInteger("Period",
                Integer.toString(this.getDateField(document.getDate(), Calendar.MONTH) + 1), this.MAX_LENGTH_2, true));
        saftInv.setInvoiceDate(this.formatDate(document.getDate()));
        if (document.isSelfBilled() != null) {
            saftInv.setSelfBillingIndicator(this.validateInteger("SelfBillingIndicator",
                    document.isSelfBilled() ? "1" : "0", this.MAX_LENGTH_1, true));
        } else {
            saftInv.setSelfBillingIndicator(0);
        }
        saftInv.setSourceID(this.validateString("InvoiceSourceID", document.getSourceId(), this.MAX_LENGTH_30, true));
        if (document.getEACCode() != null) {
            saftInv.setEACCode(this.validateString("EACCode", document.getEACCode(), this.MAX_LENGTH_5, false));
        }
        saftInv.setSystemEntryDate(this.formatDateTime(document.getCreateTimestamp()));
        UID customerUID = document.getCustomer().getUID();
        String customerID = customerUID.equals(this.config.getUID(Config.Key.Customer.Generic.UUID))
                ? "Consumidor final" : document.getCustomer().getID().toString();

        saftInv.setCustomerID(this.validateString("CustomerID", customerID, this.MAX_LENGTH_30, true));

        /* NOT REQUIRED */
        if (document.getShippingDestination() != null) {
            saftInv.setShipTo(this.getShippingPointStructure(document.getShippingDestination().getDeliveryId(),
                    document.getShippingDestination().getDate(),
                    (PTAddressEntity) document.getShippingDestination().getAddress()));
        }
        if (document.getShippingOrigin() != null) {
            saftInv.setShipFrom(this.getShippingPointStructure(document.getShippingDestination().getDeliveryId(),
                    document.getShippingDestination().getDate(),
                    (PTAddressEntity) document.getShippingOrigin().getAddress()));
        }

        return saftInv;
    }

    /**
     * Process a financial document to generate its DocumentTotals and the
     * document's entries to generate the table Line in the Invoice instance of
     * SAFT File
     *
     * @param saftInvoice
     *        - instance of Invoice (representation of financial document in
     *        SAFT XML context)
     * @param document
     *        - the document that is represented in the saftInvoice
     * @param isCredit
     *        - to distinguish between invoices/simple invoices (credit
     *        transactions) and credit notes (debit transaction)
     *
     * @throws RequiredFieldNotFoundException
     * @throws DatatypeConfigurationException
     * @throws InvalidDocumentTypeException
     * @throws InvalidTaxTypeException
     * @throws InvalidTaxCodeException
     * @throws InvalidPaymentMechanismException
     */
    private void processDocument(Invoice saftInvoice, PTGenericInvoiceEntity document, boolean isCredit)
            throws RequiredFieldNotFoundException, DatatypeConfigurationException, InvalidDocumentTypeException,
            InvalidTaxTypeException, InvalidTaxCodeException, InvalidPaymentMechanismException {
        List<PTGenericInvoiceEntryEntity> entries = document.getEntries();
        if (entries == null || entries.size() < 1) {
            throw new RequiredFieldNotFoundException(this.context + " Line");
        }

        entries.sort(Comparator.comparing(GenericInvoiceEntry::getEntryNumber));

        for (PTGenericInvoiceEntryEntity entry : entries) {
            /* REQUIRED - One Invoice.Line per IPTFinancialDocumentEntryEntity */
            Line line = new Line();
            line.setLineNumber(new BigInteger(Integer.toString(entry.getEntryNumber())));

            /* REQUIRED */
            line.setProductCode(this.validateString("ProductCode", entry.getProduct().getID().toString(),
                    this.MAX_LENGTH_30, true));
            line.setProductDescription(this.validateString("ProductDescription", entry.getProduct().getDescription(),
                    this.MAX_LENGTH_200, true));
            line.setQuantity(this.validateBigDecimal(entry.getQuantity()));
            line.setUnitOfMeasure(this.validateString("UnitOfMeasure", this.UNIT_OF_MEASURE, this.MAX_LENGTH_20, true));
            line.setUnitPrice(this.validateBigDecimal(
                    entry.getAmountWithoutTax().divide(entry.getQuantity(), this.mc.getRoundingMode())));
            line.setTaxPointDate(this.formatDate(entry.getTaxPointDate()));

            /* NOT REQUIRED - Invoice.Line.References */
            References ref = this.getReferencesForDocumentEntry(entry, document);
            if (ref != null) {
                line.getReferences().add(ref);
            }

            /* REQUIRED */
            line.setDescription(this.validateString("Description", entry.getDescription(), this.MAX_LENGTH_200, true));
            if (isCredit) {
                line.setCreditAmount(this.validateBigDecimal(entry.getAmountWithoutTax()));
            } else {
                line.setDebitAmount(this.validateBigDecimal(entry.getAmountWithoutTax()));
            }

            /* NOT REQUIRED Invoice.Line.Tax */
            if (entry.getTaxes().size() > 0) {
                PTTaxEntity taxEntity = (PTTaxEntity) entry.getTaxes().get(0);
                Tax tax = new Tax();
                tax.setTaxType(this.validateString("TaxType", this.getTaxType(taxEntity), this.MAX_LENGTH_3, true));
                tax.setTaxCode(this.validateString("TaxCode", taxEntity.getCode(), this.MAX_LENGTH_10, true));
                tax.setTaxCountryRegion(this.validateString("TaxCountryRegion",
                        this.getRegionCodeFromISOCode(((PTRegionContext) taxEntity.getContext()).getRegionCode()),
                        this.MAX_LENGTH_5, true));

                if (taxEntity.getTaxRateType().equals(TaxRateType.FLAT)) {
                    tax.setTaxAmount(this.validateBigDecimal(taxEntity.getValue()));
                } else if (taxEntity.getTaxRateType().equals(TaxRateType.PERCENTAGE)) {
                    tax.setTaxPercentage(taxEntity.getValue());
                }
                line.setTax(tax);

                if ((tax.getTaxPercentage() != null && tax.getTaxPercentage().equals(BigDecimal.ZERO)) ||
                        (tax.getTaxAmount() != null && tax.getTaxAmount().equals(BigDecimal.ZERO))) {
                    line.setTaxExemptionReason(this.validateString("TaxExemptionReason", entry.getTaxExemptionReason(),
                            this.MAX_LENGTH_60, true));
                }
            }

            /* NOT REQUIRED */
            if (entry.getDiscountAmount() != null && !entry.getDiscountAmount().equals(BigDecimal.ZERO)) {
                line.setSettlementAmount(entry.getDiscountAmount());
            }

            saftInvoice.getLine().add(line);
        }

        DocumentTotals dt = this.getDocumentTotals(document, isCredit);
        if (dt != null) {
            saftInvoice.setDocumentTotals(dt);
        }
    }

