    /**
     * Generates the field References (4.1.4.18.9) of document entry
     *
     * @param entry
     * @param document
     * @return an instance of References
     * @throws RequiredFieldNotFoundException
     * @throws DatatypeConfigurationException
     * @throws InvalidDocumentTypeException
     */
    private References getReferencesForDocumentEntry(PTGenericInvoiceEntryEntity entry, PTGenericInvoiceEntity document)
            throws RequiredFieldNotFoundException, DatatypeConfigurationException, InvalidDocumentTypeException {
        References ref = null;
        PTInvoice referencedDocument = null;
        if (PTCreditNoteEntryEntity.class.isInstance(entry)) {
            referencedDocument = ((PTCreditNoteEntryEntity) entry).getReference();
        }

        if (referencedDocument != null) {
            ref = new References();

            String reasonForCredit = "";

            if (document.getType().equals(TYPE.NC)) {
                /* then referencedDocument is an invoice/simple invoice */
                reasonForCredit = ((PTCreditNoteEntryEntity) entry).getReason();
            }

            if ((this.optionalParam = this.validateString("References.CreditNote.Reference",
                    referencedDocument.getNumber(), this.MAX_LENGTH_60, false)).length() > 0) {
                ref.setReference(this.optionalParam);
            }

            if ((this.optionalParam =
                    this.validateString("References.CreditNote.Reason", reasonForCredit, this.MAX_LENGTH_50, false))
                            .length() > 0) {
                ref.setReason(this.optionalParam);
            }
        }
        return ref;
    }

