    /**
     * Converts the product type to an acronym according to the SAFT file rules
     *
     * @param type
     * @return
     * @throws InvalidProductTypeException
     */
    private String getProductType(ProductType type) throws InvalidProductTypeException {
        switch (type) {
            case GOODS:
                return "P";
            case SERVICE:
                return "S";
            case OTHER:
                return "O";
            case CHARGE:
                return "I";
            default:
                throw new InvalidProductTypeException(type.toString());
        }
    }

