    /**
     * Generates the TaxTable of SAFT file (Table 2.5)
     *
     * @param taxEntities
     *        - the taxes to be inserted in this table
     * @return
     * @throws DatatypeConfigurationException
     * @throws RequiredFieldNotFoundException
     * @throws InvalidTaxTypeException
     * @throws InvalidTaxCodeException
     */
    private TaxTable generateTaxTable(List<PTTaxEntity> taxEntities) throws DatatypeConfigurationException,
            RequiredFieldNotFoundException, InvalidTaxTypeException, InvalidTaxCodeException {
        this.context = "TaxTable.";

        TaxTable taxTable = new TaxTable();
        for (PTTaxEntity taxEntity : taxEntities) {
            TaxTableEntry tte = new TaxTableEntry();
            tte.setTaxType(this.validateString("TaxType", this.getTaxType(taxEntity), this.MAX_LENGTH_3, true));
            tte.setTaxCode(this.validateString("TaxCode", taxEntity.getCode(), this.MAX_LENGTH_10, true));
            tte.setTaxCountryRegion(this.validateString("TaxCountryRegion",
                    this.getRegionCodeFromISOCode(((PTRegionContext) taxEntity.getContext()).getRegionCode()),
                    this.MAX_LENGTH_5, true));

            tte.setDescription(
                    this.validateString("Description", taxEntity.getDescription(), this.MAX_LENGTH_255, true));

            if (taxEntity.getValidTo() != null) {
                tte.setTaxExpirationDate(this.formatDate(taxEntity.getValidTo()));
            }

            if (taxEntity.getTaxRateType().equals(TaxRateType.FLAT)) {
                tte.setTaxAmount(taxEntity.getValue());
            } else if (taxEntity.getTaxRateType().equals(TaxRateType.PERCENTAGE)) {
                tte.setTaxPercentage(taxEntity.getValue());
            } else if (taxEntity.getTaxRateType().equals(TaxRateType.NONE)) {
                tte.setTaxPercentage(BigDecimal.ZERO);
            }

            taxTable.getTaxTableEntry().add(tte);
        }

        return taxTable;
    }

    /**
     * Generates the SourceDocuments of SAFT file (Table 4)
     *
     * @param invoices
     *        - list of invoices
     * @param simpleInvoices
     *        - list of simple invoices
     * @param creditNotes
     *        - list of credit notes
     * @return
     * @throws DatatypeConfigurationException
     * @throws RequiredFieldNotFoundException
     * @throws InvalidDocumentTypeException
     * @throws InvalidDocumentStateException
     * @throws InvalidTaxTypeException
     * @throws InvalidTaxCodeException
     * @throws InvalidPaymentMechanismException
     * @throws InvalidInvoiceTypeException
     */
    private SourceDocuments generateSourceDocuments(List<PTInvoiceEntity> invoices,
            List<PTSimpleInvoiceEntity> simpleInvoices, List<PTReceiptInvoiceEntity> receiptInvoices,
            List<PTCreditNoteEntity> creditNotes) throws DatatypeConfigurationException, RequiredFieldNotFoundException,
            InvalidDocumentTypeException, InvalidDocumentStateException, InvalidTaxTypeException,
            InvalidTaxCodeException, InvalidPaymentMechanismException, InvalidInvoiceTypeException {
        this.context = "SourceDocuments.";

        SourceDocuments srcDocs = new SourceDocuments();
        SalesInvoices salesInvoices = new SalesInvoices();
        salesInvoices.setNumberOfEntries(new BigInteger(Integer
                .toString(invoices.size() + simpleInvoices.size() + receiptInvoices.size() + creditNotes.size())));

        BigDecimal totalDebit = BigDecimal.ZERO;
        BigDecimal totalCredit = BigDecimal.ZERO;

        totalCredit = this.processInvoices(invoices, salesInvoices, totalCredit);
        totalCredit = this.processInvoices(simpleInvoices, salesInvoices, totalCredit);
        totalCredit = this.processInvoices(receiptInvoices, salesInvoices, totalCredit);

        totalDebit = this.processInvoices(creditNotes, salesInvoices, totalDebit);

        salesInvoices.setTotalDebit(this.validateBigDecimal(totalDebit));
        salesInvoices.setTotalCredit(this.validateBigDecimal(totalCredit));
        srcDocs.setSalesInvoices(salesInvoices);

        return srcDocs;
    }

    private <T extends PTGenericInvoiceEntity> BigDecimal processInvoices(List<T> invoices, SalesInvoices salesInvoices,
            BigDecimal totalCredit) throws DatatypeConfigurationException, RequiredFieldNotFoundException,
            InvalidDocumentTypeException, InvalidDocumentStateException, InvalidInvoiceTypeException,
            InvalidTaxTypeException, InvalidTaxCodeException, InvalidPaymentMechanismException {
        Invoice saftInvoice;
        for (T invoice : invoices) {
            saftInvoice = this.generateSAFTInvoice(invoice);
            this.processDocument(saftInvoice, invoice, true);
            salesInvoices.getInvoice().add(saftInvoice);

            if (!invoice.isBilled() && !invoice.isCancelled()) {
                totalCredit = totalCredit.add(invoice.getAmountWithoutTax());
            }
        }
        return totalCredit;
    }

    /**
     * Generates a financial document that will be inserted in the
     * SourceDocuments table
     *
     * @param document
     *        - can be an invoice, simple invoice or credit note
     * @return an instance of Invoice (represents a financial document in the
     *         SAFT XML context)
     *
     * @throws DatatypeConfigurationException
     * @throws RequiredFieldNotFoundException
     * @throws InvalidDocumentTypeException
     * @throws InvalidDocumentStateException
     * @throws InvalidInvoiceTypeException
     */
    private Invoice generateSAFTInvoice(PTGenericInvoiceEntity document)
            throws DatatypeConfigurationException, RequiredFieldNotFoundException, InvalidDocumentTypeException,
            InvalidDocumentStateException, InvalidInvoiceTypeException {
        Invoice saftInv = new Invoice();

        saftInv.setDocumentStatus(this.getDocumentStatus(document));

        saftInv.setInvoiceNo(this.validateString("InvoiceNo", document.getNumber(), this.MAX_LENGTH_60, true));
        saftInv.setInvoiceType(
                this.validateString("InvoiceType", this.getDocumentType(document), this.MAX_LENGTH_2, true));
        saftInv.setHash(this.validateString("Hash", document.getHash(), this.MAX_LENGTH_172, true));
        if (document.getHashControl() != null) {
            saftInv.setHashControl(
                    this.validateString("HashControl", document.getHashControl(), this.MAX_LENGTH_40, false));
        }
        saftInv.setPeriod(this.validateInteger("Period",
                Integer.toString(this.getDateField(document.getDate(), Calendar.MONTH) + 1), this.MAX_LENGTH_2, true));
        saftInv.setInvoiceDate(this.formatDate(document.getDate()));
        if (document.isSelfBilled() != null) {
            saftInv.setSelfBillingIndicator(this.validateInteger("SelfBillingIndicator",
                    document.isSelfBilled() ? "1" : "0", this.MAX_LENGTH_1, true));
        } else {
            saftInv.setSelfBillingIndicator(0);
        }
        saftInv.setSourceID(this.validateString("InvoiceSourceID", document.getSourceId(), this.MAX_LENGTH_30, true));
        if (document.getEACCode() != null) {
            saftInv.setEACCode(this.validateString("EACCode", document.getEACCode(), this.MAX_LENGTH_5, false));
        }
        saftInv.setSystemEntryDate(this.formatDateTime(document.getCreateTimestamp()));
        UID customerUID = document.getCustomer().getUID();
        String customerID = customerUID.equals(this.config.getUID(Config.Key.Customer.Generic.UUID))
                ? "Consumidor final" : document.getCustomer().getID().toString();

        saftInv.setCustomerID(this.validateString("CustomerID", customerID, this.MAX_LENGTH_30, true));

        /* NOT REQUIRED */
        if (document.getShippingDestination() != null) {
            saftInv.setShipTo(this.getShippingPointStructure(document.getShippingDestination().getDeliveryId(),
                    document.getShippingDestination().getDate(),
                    (PTAddressEntity) document.getShippingDestination().getAddress()));
        }
        if (document.getShippingOrigin() != null) {
            saftInv.setShipFrom(this.getShippingPointStructure(document.getShippingDestination().getDeliveryId(),
                    document.getShippingDestination().getDate(),
                    (PTAddressEntity) document.getShippingOrigin().getAddress()));
        }

        return saftInv;
    }

    /**
     * Process a financial document to generate its DocumentTotals and the
     * document's entries to generate the table Line in the Invoice instance of
     * SAFT File
     *
     * @param saftInvoice
     *        - instance of Invoice (representation of financial document in
     *        SAFT XML context)
     * @param document
     *        - the document that is represented in the saftInvoice
     * @param isCredit
     *        - to distinguish between invoices/simple invoices (credit
     *        transactions) and credit notes (debit transaction)
     *
     * @throws RequiredFieldNotFoundException
     * @throws DatatypeConfigurationException
     * @throws InvalidDocumentTypeException
     * @throws InvalidTaxTypeException
     * @throws InvalidTaxCodeException
     * @throws InvalidPaymentMechanismException
     */
    private void processDocument(Invoice saftInvoice, PTGenericInvoiceEntity document, boolean isCredit)
            throws RequiredFieldNotFoundException, DatatypeConfigurationException, InvalidDocumentTypeException,
            InvalidTaxTypeException, InvalidTaxCodeException, InvalidPaymentMechanismException {
        List<PTGenericInvoiceEntryEntity> entries = document.getEntries();
        if (entries == null || entries.size() < 1) {
            throw new RequiredFieldNotFoundException(this.context + " Line");
        }

        entries.sort(Comparator.comparing(GenericInvoiceEntry::getEntryNumber));

        for (PTGenericInvoiceEntryEntity entry : entries) {
            /* REQUIRED - One Invoice.Line per IPTFinancialDocumentEntryEntity */
            Line line = new Line();
            line.setLineNumber(new BigInteger(Integer.toString(entry.getEntryNumber())));

            /* REQUIRED */
            line.setProductCode(this.validateString("ProductCode", entry.getProduct().getID().toString(),
                    this.MAX_LENGTH_30, true));
            line.setProductDescription(this.validateString("ProductDescription", entry.getProduct().getDescription(),
                    this.MAX_LENGTH_200, true));
            line.setQuantity(this.validateBigDecimal(entry.getQuantity()));
            line.setUnitOfMeasure(this.validateString("UnitOfMeasure", this.UNIT_OF_MEASURE, this.MAX_LENGTH_20, true));
            line.setUnitPrice(this.validateBigDecimal(
                    entry.getAmountWithoutTax().divide(entry.getQuantity(), this.mc.getRoundingMode())));
            line.setTaxPointDate(this.formatDate(entry.getTaxPointDate()));

            /* NOT REQUIRED - Invoice.Line.References */
            References ref = this.getReferencesForDocumentEntry(entry, document);
            if (ref != null) {
                line.getReferences().add(ref);
            }

            /* REQUIRED */
            line.setDescription(this.validateString("Description", entry.getDescription(), this.MAX_LENGTH_200, true));
            if (isCredit) {
                line.setCreditAmount(this.validateBigDecimal(entry.getAmountWithoutTax()));
            } else {
                line.setDebitAmount(this.validateBigDecimal(entry.getAmountWithoutTax()));
            }

            /* NOT REQUIRED Invoice.Line.Tax */
            if (entry.getTaxes().size() > 0) {
                PTTaxEntity taxEntity = (PTTaxEntity) entry.getTaxes().get(0);
                Tax tax = new Tax();
                tax.setTaxType(this.validateString("TaxType", this.getTaxType(taxEntity), this.MAX_LENGTH_3, true));
                tax.setTaxCode(this.validateString("TaxCode", taxEntity.getCode(), this.MAX_LENGTH_10, true));
                tax.setTaxCountryRegion(this.validateString("TaxCountryRegion",
                        this.getRegionCodeFromISOCode(((PTRegionContext) taxEntity.getContext()).getRegionCode()),
                        this.MAX_LENGTH_5, true));

                if (taxEntity.getTaxRateType().equals(TaxRateType.FLAT)) {
                    tax.setTaxAmount(this.validateBigDecimal(taxEntity.getValue()));
                } else if (taxEntity.getTaxRateType().equals(TaxRateType.PERCENTAGE)) {
                    tax.setTaxPercentage(taxEntity.getValue());
                }
                line.setTax(tax);

                if ((tax.getTaxPercentage() != null && tax.getTaxPercentage().equals(BigDecimal.ZERO)) ||
                        (tax.getTaxAmount() != null && tax.getTaxAmount().equals(BigDecimal.ZERO))) {
                    line.setTaxExemptionReason(this.validateString("TaxExemptionReason", entry.getTaxExemptionReason(),
                            this.MAX_LENGTH_60, true));
                }
            }

            /* NOT REQUIRED */
            if (entry.getDiscountAmount() != null && !entry.getDiscountAmount().equals(BigDecimal.ZERO)) {
                line.setSettlementAmount(entry.getDiscountAmount());
            }

            saftInvoice.getLine().add(line);
        }

        DocumentTotals dt = this.getDocumentTotals(document, isCredit);
        if (dt != null) {
            saftInvoice.setDocumentTotals(dt);
        }
    }

