    /**
     * Generates the field References (4.1.4.18.9) of document entry
     *
     * @param entry
     * @param document
     * @return an instance of References
     * @throws RequiredFieldNotFoundException
     * @throws DatatypeConfigurationException
     * @throws InvalidDocumentTypeException
     */
    private References getReferencesForDocumentEntry(PTGenericInvoiceEntryEntity entry, PTGenericInvoiceEntity document)
            throws RequiredFieldNotFoundException, DatatypeConfigurationException, InvalidDocumentTypeException {
        References ref = null;
        PTInvoice referencedDocument = null;
        if (PTCreditNoteEntryEntity.class.isInstance(entry)) {
            referencedDocument = ((PTCreditNoteEntryEntity) entry).getReference();
        }

        if (referencedDocument != null) {
            ref = new References();

            String reasonForCredit = "";

            if (document.getType().equals(TYPE.NC)) {
                /* then referencedDocument is an invoice/simple invoice */
                reasonForCredit = ((PTCreditNoteEntryEntity) entry).getReason();
            }

            if ((this.optionalParam = this.validateString("References.CreditNote.Reference",
                    referencedDocument.getNumber(), this.MAX_LENGTH_60, false)).length() > 0) {
                ref.setReference(this.optionalParam);
            }

            if ((this.optionalParam =
                    this.validateString("References.CreditNote.Reason", reasonForCredit, this.MAX_LENGTH_50, false))
                            .length() > 0) {
                ref.setReason(this.optionalParam);
            }
        }
        return ref;
    }

    /**
     * Constructs an instance of ShippingPointStructure needed in the
     * construction of a SAFT Invoice
     *
     * @param deliveryID
     *        - the id of delivery/origin
     * @param deliveryDate
     *        - the date of delivery/origin
     * @param address
     *        - the address of delivery/origin
     * @return an instance of ShippingPointStructure
     * @throws RequiredFieldNotFoundException
     * @throws DatatypeConfigurationException
     */
    private ShippingPointStructure getShippingPointStructure(String deliveryID, Date deliveryDate,
            PTAddressEntity address) throws RequiredFieldNotFoundException, DatatypeConfigurationException {
        ShippingPointStructure sps = new ShippingPointStructure();

        if ((this.optionalParam = this.validateString("DeliveryID", deliveryID, this.MAX_LENGTH_30, false))
                .length() > 0) {
            sps.getDeliveryID().add(this.optionalParam);
        }
        if (deliveryDate != null) {
            sps.setDeliveryDate(this.formatDate(deliveryDate));
        }
        sps.setAddress(this.generateAddressStructure(address));

        return sps;
    }

    /**
     * Generates the field Currency (4.1.4.19.4) of DocumentTotals of a SAFT
     * Invoice
     *
     * @param document
     * @param isCredit
     * @return
     */
    private Currency getCurrency(PTGenericInvoiceEntity document, boolean isCredit) {
        Currency cur = null;

        if (!document.getCurrency().getCurrencyCode().equals(this.CURRENCY_CODE)) {
            cur = new Currency();
            cur.setCurrencyCode(document.getCurrency().getCurrencyCode());
            cur.setCurrencyAmount(this.validateBigDecimal(document.getAmountWithoutTax()));
        }

        return cur;
    }

    /**
     * Generates the field Settlement (4.1.4.19.5) of DocumentTotals of a SAFT
     * Invoice
     *
     * @param document
     * @return
     * @throws RequiredFieldNotFoundException
     * @throws DatatypeConfigurationException
     * @throws InvalidPaymentMechanismException
     */
    private Settlement getSettlement(PTGenericInvoiceEntity document)
            throws RequiredFieldNotFoundException, DatatypeConfigurationException, InvalidPaymentMechanismException {
        if (document.getSettlementDiscount() != null) {
            Settlement settlement = new Settlement();
            settlement.setSettlementAmount(this.validateBigDecimal(document.getSettlementDiscount()));
            settlement.setSettlementDate(this.formatDate(document.getSettlementDate()));
            if ((this.optionalParam = this.validateString("SettlementDiscount", document.getSettlementDescription(),
                    this.MAX_LENGTH_30, false)).length() > 0) {
                settlement.setSettlementDiscount(this.optionalParam);
            }

            if (settlement.getSettlementAmount() != null &&
                    !settlement.getSettlementAmount().equals(this.validateBigDecimal(BigDecimal.ZERO))) {
                return settlement;
            } else {
                return null;
            }
        }
        return null;
    }

    /**
     * Generates the DocumentTotals (4.1.4.19) of a SAFT Invoice
     *
     * @param document
     * @param isCredit
     * @return
     * @throws RequiredFieldNotFoundException
     * @throws DatatypeConfigurationException
     * @throws InvalidPaymentMechanismException
     */
    private DocumentTotals getDocumentTotals(PTGenericInvoiceEntity document, boolean isCredit)
            throws RequiredFieldNotFoundException, DatatypeConfigurationException, InvalidPaymentMechanismException {
        DocumentTotals dt = null;

        if (!this.validateBigDecimal(document.getAmountWithoutTax()).equals(this.validateBigDecimal(BigDecimal.ZERO))) {
            dt = new DocumentTotals(); // 4.1.4.19
            /* REQUIRED */
            // 4.1.4.19.1
            dt.setTaxPayable(this.validateBigDecimal(document.getTaxAmount()));
            // 4.1.4.19.2
            dt.setNetTotal(this.validateBigDecimal(document.getAmountWithoutTax()));
            // 4.1.4.19.3
            dt.setGrossTotal(this.validateBigDecimal(document.getAmountWithTax()));

            /*
             * NOT REQUIRED - I guess it's only required if it has another
             * currency
             */
            // 4.1.4.19.4
            Currency cur = this.getCurrency(document, isCredit);
            if (cur != null) {
                dt.setCurrency(cur);
            }

            /* NOT REQUIRED - Invoice.DocumentTotals.Settlements */
            Settlement stlment = this.getSettlement(document); // 4.1.4.19.5
            if (stlment != null) {
                dt.getSettlement().add(stlment);
            }

            List<Payment> payments = this.getPaymentsList(document);
            if (payments != null) {
                for (Payment p : payments) {
                    dt.getPayment().add(p);
                }
            }
        }

        return dt;
    }

    /**
     * Generates the InvoiceType (4.1.4.7) of a SAFT Invoice
     *
     * @param document
     * @return
     * @throws InvalidInvoiceTypeException
     */
    private String getDocumentType(PTGenericInvoiceEntity document) throws InvalidInvoiceTypeException {
        switch (document.getType()) {
            case FS:
                return "FS";
            case FT:
                return "FT";
            case FR:
                return "FR";
            case NC:
                return "NC";
            case ND:
                return "ND";
            default:
                throw new InvalidInvoiceTypeException(document.getType().toString(), document.getSeries());

        }
    }

