        Scanner menuScanner = new Scanner (System.in);
        int menuChoice;

        for (int i = 0; i < opts.length; i++)
        {
            System.out.println((i+1)+". "+opts[i]);
        }

        menuChoice = menuScanner.nextInt();

        return opts[menuChoice-1];
    }

