    return b.<MemberAccessTree>nonterminal(PHPLexicalGrammar.CLASS_MEMBER_ACCESS).is(
      f.classMemberAccess(
        b.token(DOUBLECOLON),
        b.firstOf(
          VARIABLE_WITHOUT_OBJECTS(),
