package org.sonar.php.parser;

import com.sonar.sslr.api.GenericTokenType;
import org.sonar.php.api.PHPKeyword;
import org.sonar.php.api.PHPPunctuator;
import org.sonar.sslr.grammar.GrammarRuleKey;
import org.sonar.sslr.grammar.LexerlessGrammarBuilder;
import org.sonar.sslr.parser.LexerlessGrammar;

public enum PHPLexicalGrammar implements GrammarRuleKey {

  COMPILATION_UNIT,
  SCRIPT,

  /**
   * Declaration
   */

  FUNCTION_DECLARATION,
  CLASS_DECLARATION,
  INTERFACE_DECLARATION,
  TRAIT_DECLARATION,
  ENUM_DECLARATION,

  CLASS_MEMBER,
  ENUM_MEMBER,

  METHOD_DECLARATION,
  CLASS_VARIABLE_DECLARATION,
  CLASS_CONSTANT_DECLARATION,
  TRAIT_USE_STATEMENT,

  NAMESPACE_NAME,
  INTERFACE_LIST,
  PARAMETER_LIST,
  PARAMETER,

  VARIABLE_DECLARATION,
  MEMBER_MODIFIER,
  CLASS_CONST_MODIFIER,
  VISIBILITY_MODIFIER,
  MEMBER_CONST_DECLARATION,
  FUNCTION_CALL_ARGUMENT,

  TRAIT_METHOD_REFERENCE_FULLY_QUALIFIED,
  TRAIT_METHOD_REFERENCE,
  TRAIT_ALIAS,
  TRAIT_PRECEDENCE,

  TYPE,
  TYPE_NAME,
  RETURN_TYPE_CLAUSE,
  UNION_TYPE,
  INTERSECTION_TYPE,
  DECLARED_TYPE,

  /**
   * Lexical
   */
  EOF,
  NOWDOC,
  HEREDOC,
  HEREDOC_BODY,
  NUMERIC_LITERAL,
  STRING_LITERAL,
  STRING_WITH_ENCAPS_VAR_CHARACTERS,
  STRING_CHARACTERS_EXECUTION,
  HEREDOC_STRING_CHARACTERS,
  ENCAPS_VAR_IDENTIFIER,
  REGULAR_VAR_IDENTIFIER,
  VARIABLE_IDENTIFIER,
  IDENTIFIER,
  IDENTIFIER_OR_KEYWORD,
  FILE_OPENING_TAG,
  ANYTHING_BUT_START_TAG,
  INLINE_HTML,
  KEYWORDS,

  /**
   * SPACING
   */
  SPACING,

  /**
   * End of statement.
   */
  EOS,

  /**
   * Statement
   */
  TOP_STATEMENT,
  STATEMENT,
  INNER_STATEMENT,

  BLOCK,

  EMPTY_STATEMENT,

  INLINE_HTML_STATEMENT,

  NAMESPACE_STATEMENT,
  DECLARE_STATEMENT,

  CONSTANT_DECLARATION,
  CONSTANT_VAR,

  USE_STATEMENT,
  USE_CLAUSE,
  GROUP_USE_CLAUSE,

  EXPRESSION_STATEMENT,
  EXPRESSION_LIST_STATEMENT,
  ECHO_STATEMENT,

  IF_STATEMENT,
  ELSEIF_CLAUSE,
  ELSE_CLAUSE,
  ALTERNATIVE_IF_STATEMENT,
  STANDARD_IF_STATEMENT,
  ALTERNATIVE_ELSEIF_CLAUSE,
  ALTERNATIVE_ELSE_CLAUSE,

  WHILE_STATEMENT,
  ALTERNATIVE_WHILE_STATEMENT,

  DO_WHILE_STATEMENT,

  FOR_STATEMENT,
  FOR_EXPR,

  FOREACH_STATEMENT,
  FOREACH_VARIABLE,

  MATCH_EXPRESSION,
  MATCH_CLAUSE,

  SWITCH_STATEMENT,
  SWITCH_CASE_CLAUSE,

  LABEL,
  BREAK_STATEMENT,
  CONTINUE_STATEMENT,
  RETURN_STATEMENT,
  THROW_STATEMENT,
  GOTO_STATEMENT,

  TRY_STATEMENT,
  CATCH_BLOCK,

  GLOBAL_STATEMENT,
  GLOBAL_VAR,
  STATIC_STATEMENT,
  STATIC_VAR,
  UNSET_VARIABLE_STATEMENT,
  UNSET_VARIABLES,

  ENUM_CASE,

  /**
   * Expression
   */
  PRIMARY_EXPRESSION,
  MEMBER_EXPRESSION,
  NEW_OBJECT_EXPRESSION,
  NEW_OBJECT_CLASS_FIELD_ACCESS,
  SPECIAL_CALL,
  VARIABLE_WITHOUT_OBJECTS,
  CLASS_MEMBER_ACCESS,
  OBJECT_MEMBER_ACCESS,
  FUNCTION_CALL_PARAMETER_LIST,
  DIMENSIONAL_OFFSET,
  STATIC_SCALAR,
  ARRAY_INIALIZER,
  COMMON_SCALAR,
  YIELD_SCALAR,
  BOOLEAN_LITERAL,
  LEXICAL_VARIABLE,
  ASSIGNMENT_EXPRESSION,
