  CAST_TYPE,
  INTERNAL_FUNCTION,
  ARRAY_PAIR_LIST,
  LIST_EXPRESSION_ASSIGNMENT,
  ARRAY_DESTRUCTURING_ASSIGNMENT,
  ARRAY_ASSIGNMENT_PATTERN_ELEMENT,
  COMPLEX_ENCAPS_VARIABLE,
  SEMI_COMPLEX_ENCAPS_VARIABLE,
  SEMI_COMPLEX_RECOVERY_EXPRESSION,
  SIMPLE_ENCAPS_VARIABLE,
  ENCAPS_VAR,
  EXIT_EXPRESSION,
  CALLABLE_CONVERT,

  NULL,
  CLASS_CONSTANT,
  FILE_CONSTANT,
  DIR_CONSTANT,
