package org.urish.gwtit.dev.linker;

import java.util.Set;

import com.google.gwt.core.ext.LinkerContext;
import com.google.gwt.core.ext.TreeLogger;
import com.google.gwt.core.ext.UnableToCompleteException;
import com.google.gwt.core.ext.linker.AbstractLinker;
import com.google.gwt.core.ext.linker.ArtifactSet;
import com.google.gwt.core.ext.linker.CompilationResult;
import com.google.gwt.core.ext.linker.LinkerOrder;
import com.google.gwt.core.ext.linker.LinkerOrder.Order;
import com.google.gwt.dev.util.DefaultTextOutput;

/**
 * Simple linker to remove a lot of GWT fluff. Heavily based on gwt-node by Chad
 * Retz.
 * 
 * @author Uri Shaked
 */
@LinkerOrder(Order.PRIMARY)
public class GwtTitaniumLinker extends AbstractLinker {

	@Override
	public String getDescription() {
		return "GwtTitanium";
	}

	@Override
	public ArtifactSet link(TreeLogger logger, LinkerContext context, ArtifactSet artifacts)
			throws UnableToCompleteException {
		ArtifactSet toReturn = new ArtifactSet(artifacts);
		DefaultTextOutput out = new DefaultTextOutput(true);
		out.print("(function () {");
		out.newline();
		// grab compilation result
		Set<CompilationResult> results = artifacts.find(CompilationResult.class);
		if (results.size() == 0) {
			logger.log(TreeLogger.WARN, "Requested 0 permutations");
			return toReturn;
