            settings.setStatusUpdatesEnabled(gcsd.getStatusUpdatesEnabled());
            settings.setStatusUpdateRate(gcsd.getStatusUpdatesRate());
            settings.setDisplayStateColor(gcsd.getDisplayStateColor());
